/**
 * @file
 * @brief Test file for the Zephyr kernel's polling API (k_poll).
 *
 * This file contains a comprehensive set of tests for various functionalities
 * provided by the k_poll API, including polling on signals, semaphores,
 * message queues, and handling timeouts and multiple events.
 */

#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/irq_offload.h> /* For ISR context tests, if any */

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

/*
 * Global kernel objects used across various poll tests.
 * These are defined globally to be accessible by test threads and main test functions.
 */

/* K_POLL_SIGNAL objects and their corresponding K_POLL_EVENT objects */
K_POLL_SIGNAL_DEFINE(poll_signal_basic);
K_POLL_EVENT_DEFINE(poll_event_signal_basic);

K_POLL_SIGNAL_DEFINE(poll_signal_timeout);
K_POLL_EVENT_DEFINE(poll_event_signal_timeout);

K_POLL_SIGNAL_DEFINE(poll_signal_multi_1);
K_POLL_EVENT_DEFINE(poll_event_signal_multi_1);

/*
 * Test objects for k_sem
 */
K_SEM_DEFINE(poll_sem_basic, 0, 1);
K_POLL_EVENT_DEFINE(poll_event_sem_basic);

K_SEM_DEFINE(poll_sem_multi_1, 0, 1);
K_POLL_EVENT_DEFINE(poll_event_sem_multi_1);

/*
 * Test objects for k_msgq
 */
K_MSGQ_DEFINE(poll_msgq_basic, sizeof(int), 1, 4);
K_POLL_EVENT_DEFINE(poll_event_msgq_basic);

/*
 * Thread stack and data for the signal raiser thread.
 */
K_THREAD_STACK_DEFINE(poll_signal_raiser_stack, STACK_SIZE);
struct k_thread poll_signal_raiser_data;

/*
 * Helper thread entry function for raising a k_poll_signal.
 * This function is designed to be run in a separate thread to simulate
 * an asynchronous event that the main test thread is polling for.
 */
static void poll_signal_raiser_thread_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    /*
     * Introduce a small delay to ensure the main test thread has entered
     * the k_poll() state before the signal is raised. This prevents a race
     * condition where the signal might be raised and missed if k_poll()
     * hasn't started waiting yet.
     */
    k_msleep(100);

    /*
     * This is the specific line that caused the compilation error.
     * The original code likely had 'k_poll_signal_int(&poll_signal_basic, 123);'
     * The correct Zephyr API function to raise a k_poll_signal and
     * associate an integer result value with it is 'k_poll_signal_raise'.
     *
     * The compiler error message:
     * "/zephyrproject/zephyr/tests/kernel/poll/src/test_poll.c:80:9: error: implicit declaration of function 'k_poll_signal_int'; did you mean 'k_poll_signal_init'? [-Wimplicit-function-declaration]"
     * clearly indicates the function name was wrong.
     */
    k_poll_signal_raise(&poll_signal_basic, 123); /* This should be line 80 */
}

/**
 * @brief Test case for basic k_poll_signal_raise functionality.
 *
 * Verifies that a thread can successfully poll on a k_poll_signal
 * and receive the expected result when the signal is raised by another thread.
 */
ZTEST(poll_api, test_k_poll_signal_raise_basic)
{
    /* Initialize the poll signal and event object */
    k_poll_signal_init(&poll_signal_basic);
    k_poll_event_init(&poll_event_signal_basic, K_POLL_TYPE_SIGNAL,
                      K_POLL_MODE_NOTIFY_ALL, &poll_signal_basic);

    /* Create and start the signal raiser thread */
    k_thread_create(&poll_signal_raiser_data, poll_signal_raiser_stack,
                    K_THREAD_STACK_SIZEOF(poll_signal_raiser_stack),
                    poll_signal_raiser_thread_entry, NULL, NULL, NULL,
                    K_PRIO_COOP(7), 0, K_NO_WAIT);

    /* Wait indefinitely for the signal using k_poll */
    int ret = k_poll(&poll_event_signal_basic, 1, K_FOREVER);

    /* Assertions to verify the poll operation and signal state */
    zassert_equal(ret, 0, "k_poll failed to wait for signal");
    zassert_equal(poll_event_signal_basic.state, K_POLL_STATE_SIGNALED,
                  "Poll event state is not K_POLL_STATE_SIGNALED");
    zassert_equal(poll_signal_basic.result, 123, "Signal result value is incorrect");
    zassert_equal(poll_signal_basic.called, 1, "Signal called count is incorrect");

    /* Clean up the signal for subsequent tests */
    k_poll_signal_cleanup(&poll_signal_basic);
}

/*
 * Thread stack and data for the semaphore giver thread.
 */
K_THREAD_STACK_DEFINE(poll_sem_giver_stack, STACK_SIZE);
struct k_thread poll_sem_giver_data;

/*
 * Helper thread entry function for giving a k_sem.
 */
static void poll_sem_giver_thread_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_msleep(100);
    k_sem_give(&poll_sem_basic);
}

/**
 * @brief Test case for basic k_poll_sem functionality.
 *
 * Verifies that a thread can successfully poll on a k_sem
 * and acquire it when the semaphore is given by another thread.
 */
ZTEST(poll_api, test_k_poll_sem_basic)
{
    k_poll_event_init(&poll_event_sem_basic, K_POLL_TYPE_SEM_AVAILABLE,
                      K_POLL_MODE_NOTIFY_ALL, &poll_sem_basic);

    k_thread_create(&poll_sem_giver_data, poll_sem_giver_stack,
                    K_THREAD_STACK_SIZEOF(poll_sem_giver_stack),
                    poll_sem_giver_thread_entry, NULL, NULL, NULL,
                    K_PRIO_COOP(7), 0, K_NO_WAIT);

    int ret = k_poll(&poll_event_sem_basic, 1, K_FOREVER);

    zassert_equal(ret, 0, "k_poll failed to wait for semaphore");
    zassert_equal(poll_event_sem_basic.state, K_POLL_STATE_SEM_AVAILABLE,
                  "Poll event state is not K_POLL_STATE_SEM_AVAILABLE");
    zassert_equal(k_sem_count_get(&poll_sem_basic), 0, "Semaphore was not taken by k_poll");
}

/*
 * Thread stack and data for the message queue putter thread.
 */
K_THREAD_STACK_DEFINE(poll_msgq_putter_stack, STACK_SIZE);
struct k_thread poll_msgq_putter_data;

/*
 * Helper thread entry function for putting a message into a k_msgq.
 */
static void poll_msgq_putter_thread_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_msleep(100);
    int val = 42;
    k_msgq_put(&poll_msgq_basic, &val, K_FOREVER);
}

/**
 * @brief Test case for basic k_poll_msgq functionality.
 *
 * Verifies that a thread can successfully poll on a k_msgq
 * and receive data when a message is put into the queue by another thread.
 */
ZTEST(poll_api, test_k_poll_msgq_basic)
{
    k_poll_event_init(&poll_event_msgq_basic, K_POLL_TYPE_MSGQ_DATA_AVAILABLE,
                      K_POLL_MODE_NOTIFY_ALL, &poll_msgq_basic);

    k_thread_create(&poll_msgq_putter_data, poll_msgq_putter_stack,
                    K_THREAD_STACK_SIZEOF(poll_msgq_putter_stack),
                    poll_msgq_putter_thread_entry, NULL, NULL, NULL,
                    K_PRIO_COOP(7), 0, K_NO_WAIT);

    int ret = k_poll(&poll_event_msgq_basic, 1, K_FOREVER);

    zassert_equal(ret, 0, "k_poll failed to wait for message queue");
    zassert_equal(poll_event_msgq_basic.state, K_POLL_STATE_MSGQ_DATA_AVAILABLE,
                  "Poll event state is not K_POLL_STATE_MSGQ_DATA_AVAILABLE");
    int val_received;
    zassert_equal(k_msgq_get(&poll_msgq_basic, &val_received, K_NO_WAIT), 0,
                  "Failed to get message from queue after poll");
    zassert_equal(val_received, 42, "Received message value is incorrect");
}

/**
 * @brief Test case for k_poll timeout functionality.
 *
 * Verifies that k_poll returns -EAGAIN when a timeout occurs
 * and no event becomes ready within the specified duration.
 */
ZTEST(poll_api, test_k_poll_timeout_basic)
{
    k_poll_signal_init(&poll_signal_timeout);
    k_poll_event_init(&poll_event_signal_timeout, K_POLL_TYPE_SIGNAL,
                      K_POLL_MODE_NOTIFY_ALL, &poll_signal_timeout);

    int ret = k_poll(&poll_event_signal_timeout, 1, K_MSEC(100));
    zassert_equal(ret, -EAGAIN, "k_poll did not return -EAGAIN on timeout");

    k_poll_signal_cleanup(&poll_signal_timeout);
}

/*
 * Thread stack and data for the multiple event trigger thread.
 */
K_THREAD_STACK_DEFINE(poll_multi_event_trigger_stack, STACK_SIZE);
struct k_thread poll_multi_event_trigger_data;

/*
 * Helper thread entry function for triggering one of multiple events.
 */
static void poll_multi_event_trigger_thread_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_msleep(100);
    /* Trigger the semaphore event */
    k_sem_give(&poll_sem_multi_1);
}

/**
 * @brief Test case for k_poll with multiple events.
 *
 * Verifies that k_poll correctly identifies and returns when one of
 * multiple registered events becomes ready.
 */
ZTEST(poll_api, test_k_poll_multiple_events)
{
    k_poll_signal_init(&poll_signal_multi_1);
    k_sem_init(&poll_sem_multi_1, 0, 1);

    K_POLL_EVENT_DEFINE(events[2]);

    k_poll_event_init(&events[0], K_POLL_TYPE_SIGNAL,
                      K_POLL_MODE_NOTIFY_ALL, &poll_signal_multi_1);
    k_poll_event_init(&events[1], K_POLL_TYPE_SEM_AVAILABLE,
                      K_POLL_MODE_NOTIFY_ALL, &poll_sem_multi_1);

    k_thread_create(&poll_multi_event_trigger_data, poll_multi_event_trigger_stack,
                    K_THREAD_STACK_SIZEOF(poll_multi_event_trigger_stack),
                    poll_multi_event_trigger_thread_entry, NULL, NULL, NULL,
                    K_PRIO_COOP(7), 0, K_NO_WAIT);

    int ret = k_poll(events, 2, K_FOREVER);

    zassert_equal(ret, 0, "k_poll failed for multiple events");
    zassert_equal(events[0].state, K_POLL_STATE_NOT_READY,
                  "Signal event should not have been ready");
    zassert_equal(events[1].state, K_POLL_STATE_SEM_AVAILABLE,
                  "Semaphore event should have been ready");

    k_poll_signal_cleanup(&poll_signal_multi_1);
    k_sem_reset(&poll_sem_multi_1);
}

ZTEST_SUITE(poll_api, NULL, NULL, NULL, NULL, NULL);
